import { Check, ChevronsUpDown, ExternalLink } from "lucide-react";
import { useState } from "react";

import { cn } from "@/lib/utils";
import {
  AvatarFallback,
  AvatarImage,
  AvatarRoot,
} from "@/registry/thornberry/components/avatar";
import { Button } from "@/registry/thornberry/components/button";
import {
  MenuContent,
  MenuItem,
  MenuItemGroup,
  MenuItemGroupLabel,
  MenuPositioner,
  MenuRoot,
  MenuSeparator,
  MenuTrigger,
} from "@/registry/thornberry/components/menu";

import type { KeyboardEvent, PointerEvent, ReactNode } from "react";

/** A selectable workspace (Omni organization) in the switcher. */
export interface WorkspaceOption {
  id: string;
  name: string;
  /** The workspace's `@handle`, shown under its name in the list when set. */
  slug?: string | null;
  /** Logo URL, if set; falls back to the name's first letter. */
  logo?: string | null;
  /**
   * Secondary line under the name (e.g. the viewer's role in the workspace).
   * Shown in place of the `@handle` when set.
   */
  description?: string | null;
  /** Short tag beside the name (e.g. "Personal"). */
  badge?: string | null;
}

/** An extra entry below the workspace list (create, browse all, manage). */
export interface WorkspaceSwitcherAction {
  /** Stable key, unique among the actions. */
  id: string;
  label: string;
  /** Leading icon; a lucide icon sized by the menu item. */
  icon?: ReactNode;
  /** Link the entry opens. Without it the entry only calls `onSelect`. */
  href?: string;
  /** Open `href` in a new tab, marked with an external-link icon. */
  external?: boolean;
  /** Called when the entry is chosen (e.g. an in-app navigate). */
  onSelect?: () => void;
}

export interface WorkspaceSwitcherProps {
  /** Workspaces the signed-in user belongs to. */
  workspaces: WorkspaceOption[];
  /**
   * Id of the currently active workspace. When it is missing or not in the
   * list, the trigger shows `placeholder` and still opens the list.
   */
  currentWorkspaceId?: string | null;
  /** Called with the selected workspace id. */
  onSelect: (id: string) => void;
  /**
   * Called when a workspace entry is highlighted by pointer or keyboard,
   * before it is chosen. Use it to preload the workspace's route or data.
   */
  onItemIntent?: (id: string) => void;
  /** Extra entries below the list, in order (create, browse all, ...). */
  actions?: WorkspaceSwitcherAction[];
  /** Optional link to manage workspaces (e.g. the identity dashboard). */
  manageUrl?: string;
  manageLabel?: string;
  groupLabel?: string;
  /** Trigger text when no workspace is active. */
  placeholder?: string;
  /**
   * Render nothing for a user with one workspace (and no actions), instead of
   * a static label.
   */
  hideWhenSingle?: boolean;
  /**
   * Layout: "header" is a compact button (top bars); "sidebar" is a full-width
   * row (nav rails) that shrinks to the avatar in a collapsed icon sidebar.
   * Defaults to "header".
   */
  variant?: "header" | "sidebar";
  className?: string;
}

/** Menu value prefix of action entries, never passed to `onSelect` */
const ACTION_PREFIX = "action:";

/** Menu value of the manage link */
const MANAGE_ID = "manage-workspaces";

/** Workspace avatar: logo if set, else the first letter of the name. */
const WorkspaceAvatar = ({ workspace }: { workspace: WorkspaceOption }) => (
  <AvatarRoot className="size-5 shrink-0 text-xs">
    <AvatarImage src={workspace.logo ?? undefined} alt={workspace.name} />
    <AvatarFallback>{workspace.name?.[0]?.toUpperCase()}</AvatarFallback>
  </AvatarRoot>
);

const WorkspaceBadge = ({ children }: { children: ReactNode }) => (
  <span className="bg-muted text-muted-foreground shrink-0 rounded-sm px-1.5 py-0.5 text-xs leading-none font-medium">
    {children}
  </span>
);

/**
 * Workspace (organization) switcher, shared across Omni apps.
 *
 * Presentational and data-agnostic: the host app supplies the workspaces, the
 * active id, and the select handler (which may navigate, set a cookie, close a
 * mobile sidebar, etc.). A single-workspace user with no actions sees a static
 * label (no dropdown), or nothing with `hideWhenSingle`. Creating and managing
 * workspaces is delegated to the identity dashboard via `actions`/`manageUrl`.
 */
const WorkspaceSwitcher = ({
  workspaces,
  currentWorkspaceId,
  onSelect,
  onItemIntent,
  actions = [],
  manageUrl,
  manageLabel = "Manage workspaces",
  groupLabel = "Workspaces",
  placeholder = "Select workspace",
  hideWhenSingle = false,
  variant = "header",
  className,
}: WorkspaceSwitcherProps) => {
  // Whether the trigger sits in a collapsed icon sidebar, read as it is pressed
  // so the menu opens beside the rail instead of hanging off its narrow width
  const [inCollapsedRail, setInCollapsedRail] = useState(false);

  const current = workspaces.find(
    (workspace) => workspace.id === currentWorkspaceId,
  );

  const entries: WorkspaceSwitcherAction[] = manageUrl
    ? [
        ...actions,
        { id: MANAGE_ID, label: manageLabel, href: manageUrl, external: true },
      ]
    : actions;

  const isSidebar = variant === "sidebar";
  const hasMenu = workspaces.length > 1 || entries.length > 0 || !current;

  if (!workspaces.length && !entries.length) return null;
  if (hideWhenSingle && workspaces.length <= 1 && !entries.length) return null;

  const label = current?.name ?? placeholder;

  const triggerContent = (
    <>
      {current && <WorkspaceAvatar workspace={current} />}
      {/* Visually hidden, not removed, in a collapsed icon sidebar, so the
          trigger keeps its accessible name */}
      <span
        className={cn(
          "truncate",
          isSidebar &&
            "flex-1 font-medium group-data-[collapsible=icon]:sr-only",
          !current && "text-muted-foreground",
        )}
      >
        {label}
      </span>
      {hasMenu && (
        <ChevronsUpDown
          className={cn(
            "size-4 shrink-0 opacity-60",
            // With no avatar to show, the chevron stands in for the trigger
            isSidebar && current && "group-data-[collapsible=icon]:hidden",
          )}
        />
      )}
    </>
  );

  const sidebarTriggerClass = cn(
    "flex w-full items-center gap-2 rounded-lg border bg-background px-2.5 py-2 text-left text-sm transition-colors hover:bg-accent/60",
    // A collapsed icon sidebar keeps just the avatar
    "group-data-[collapsible=icon]:size-8 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:p-0",
    className,
  );
  const headerTriggerClass = cn("max-w-44 gap-2", className);

  // Single workspace and nothing else to offer: a static label, no dropdown
  if (!hasMenu) {
    return isSidebar ? (
      <div className={cn(sidebarTriggerClass, "cursor-default")}>
        {triggerContent}
      </div>
    ) : (
      <Button
        variant="outline"
        size="sm"
        className={cn(headerTriggerClass, "cursor-default")}
        aria-disabled
      >
        {triggerContent}
      </Button>
    );
  }

  const handleSelect = (value: string) => {
    if (!value.startsWith(ACTION_PREFIX)) {
      onSelect(value);
      return;
    }
    // Links navigate on their own; only the callback runs here
    const action = entries.find(
      (entry) => `${ACTION_PREFIX}${entry.id}` === value,
    );
    action?.onSelect?.();
  };

  const detectRail = (
    event: PointerEvent<HTMLElement> | KeyboardEvent<HTMLElement>,
  ) => {
    setInCollapsedRail(
      !!event.currentTarget.closest("[data-collapsible='icon']"),
    );
  };

  return (
    <MenuRoot
      // In a nav rail the list drops straight down at the row's own width; a
      // collapsed rail opens it to the side
      {...(isSidebar && {
        positioning: inCollapsedRail
          ? { placement: "right-start" }
          : { placement: "bottom-start", sameWidth: true },
      })}
      onSelect={(details) => handleSelect(details.value)}
      {...(onItemIntent && {
        onHighlightChange: ({ highlightedValue }) => {
          if (highlightedValue && !highlightedValue.startsWith(ACTION_PREFIX))
            onItemIntent(highlightedValue);
        },
      })}
    >
      <MenuTrigger
        asChild
        aria-label={`${label}, switch workspace`}
        {...(isSidebar && {
          onPointerDown: detectRail,
          onKeyDown: detectRail,
        })}
      >
        {isSidebar ? (
          <button type="button" className={sidebarTriggerClass}>
            {triggerContent}
          </button>
        ) : (
          <Button variant="outline" size="sm" className={headerTriggerClass}>
            {triggerContent}
          </Button>
        )}
      </MenuTrigger>

      <MenuPositioner>
        <MenuContent
          className={
            isSidebar
              ? // A collapsed rail is too narrow to match, so keep a floor
                cn("w-full min-w-0", inCollapsedRail && "min-w-52")
              : "min-w-52"
          }
        >
          {workspaces.length > 0 && (
            // The list scrolls on its own so the actions stay in view
            <MenuItemGroup className="max-h-80 min-h-0 overflow-y-auto overscroll-contain">
              <MenuItemGroupLabel className="bg-popover sticky top-0 z-10">
                {groupLabel}
              </MenuItemGroupLabel>
              {workspaces.map((workspace) => {
                const subtitle =
                  workspace.description ??
                  (workspace.slug ? `@${workspace.slug}` : null);

                return (
                  <MenuItem
                    key={workspace.id}
                    value={workspace.id}
                    className="gap-2"
                  >
                    <WorkspaceAvatar workspace={workspace} />
                    <span className="flex min-w-0 flex-1 flex-col">
                      <span className="flex min-w-0 items-center gap-1.5">
                        <span className="truncate">{workspace.name}</span>
                        {workspace.badge && (
                          <WorkspaceBadge>{workspace.badge}</WorkspaceBadge>
                        )}
                      </span>
                      {subtitle && (
                        <span className="text-muted-foreground truncate text-xs">
                          {subtitle}
                        </span>
                      )}
                    </span>
                    {workspace.id === currentWorkspaceId && (
                      <Check className="size-4 shrink-0" />
                    )}
                  </MenuItem>
                );
              })}
            </MenuItemGroup>
          )}

          {entries.length > 0 && (
            <>
              {workspaces.length > 0 && <MenuSeparator />}
              {entries.map((entry) => {
                const value = `${ACTION_PREFIX}${entry.id}`;
                const content = (
                  <>
                    {entry.icon}
                    <span className="flex-1 truncate">{entry.label}</span>
                    {entry.external && entry.icon && (
                      <ExternalLink className="size-3.5 opacity-60" />
                    )}
                  </>
                );

                return entry.href ? (
                  <MenuItem key={entry.id} value={value} asChild>
                    <a
                      href={entry.href}
                      {...(entry.external && {
                        target: "_blank",
                        rel: "noreferrer",
                      })}
                      className="text-muted-foreground"
                    >
                      {entry.external && !entry.icon && (
                        <ExternalLink className="size-4" />
                      )}
                      {content}
                    </a>
                  </MenuItem>
                ) : (
                  <MenuItem
                    key={entry.id}
                    value={value}
                    className="text-muted-foreground"
                  >
                    {content}
                  </MenuItem>
                );
              })}
            </>
          )}
        </MenuContent>
      </MenuPositioner>
    </MenuRoot>
  );
};

export { WorkspaceSwitcher };

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};

import { Avatar as ArkAvatar, useAvatar as useArkAvatar } from "@ark-ui/react";
import { cva } from "class-variance-authority";

import { cn } from "@/lib/utils";

import type { VariantProps } from "class-variance-authority";
import type { ComponentProps, ReactNode } from "react";

const avatarVariants = cva(
  "relative flex shrink-0 items-center justify-center overflow-hidden rounded-full",
  {
    variants: {
      size: {
        xs: "size-8 text-xs",
        sm: "size-9 text-sm",
        md: "text-md size-10",
        lg: "size-11 text-lg",
        xl: "size-12 text-xl",
      },
    },
    defaultVariants: { size: "md" },
  },
);

const useAvatar = useArkAvatar;

const AvatarProvider = ({
  className,
  size,
  ...rest
}: ComponentProps<typeof ArkAvatar.RootProvider> &
  VariantProps<typeof avatarVariants>) => (
  <ArkAvatar.RootProvider
    className={cn(avatarVariants({ size, className }))}
    {...rest}
  />
);

const AvatarRoot = ({
  className,
  size,
  ...rest
}: ComponentProps<typeof ArkAvatar.Root> &
  VariantProps<typeof avatarVariants>) => (
  <ArkAvatar.Root
    className={cn(avatarVariants({ size, className }))}
    {...rest}
  />
);

const AvatarFallback = ({
  className,
  ...rest
}: ComponentProps<typeof ArkAvatar.Fallback>) => (
  <ArkAvatar.Fallback
    className={cn(
      "flex size-full items-center justify-center rounded-full bg-muted",
      className,
    )}
    {...rest}
  />
);

const AvatarImage = ({
  className,
  ...rest
}: ComponentProps<typeof ArkAvatar.Image>) => (
  <ArkAvatar.Image
    // Render the image even before it decodes (overriding Ark's `hidden`) so it
    // can cross-fade in via opacity rather than snapping from display:none. Ark
    // flips `data-state` to "visible" once it loads, driving the fade; a
    // broken/loading one stays at opacity 0 with the fallback behind it.
    hidden={false}
    ref={(img) => {
      if (!img) return;
      // Only a cached, already-decoded image is shown instantly (transition
      // suppressed) so a page of cached avatars never mass-fades at once. Every
      // other case, no src, still loading, or a broken/stale src left mounted
      // by `hidden={false}` after the avatar is cleared, hands control back to
      // the data-state class so the image stays at opacity-0 and the fallback
      // shows, instead of a leftover inline opacity keeping a broken glyph or
      // the `alt` text visible until a refresh.
      if (img.getAttribute("src") && img.complete && img.naturalWidth > 0) {
        img.style.transition = "none";
        img.style.opacity = "1";
      } else {
        img.style.opacity = "";
        img.style.transition = "";
      }
    }}
    className={cn(
      // `absolute inset-0` overlays the image on the fallback instead of leaving
      // it in flow. Because `hidden={false}` keeps the <img> mounted while it
      // loads or after it errors, an in-flow image would be a second flex child
      // of the flex root and split the row with the fallback, shoving the
      // fallback initial off-center. Taking it out of flow lets the fallback own
      // the full circle so its initial stays centered.
      "absolute inset-0 aspect-square size-full object-cover opacity-0 transition-opacity duration-300 ease-out data-[state=visible]:opacity-100",
      className,
    )}
    alt="Avatar"
    {...rest}
  />
);

interface AvatarProps extends ComponentProps<typeof AvatarRoot> {
  /** Image URL; the fallback shows while it loads, or when unset or broken. */
  src?: string | null;
  alt?: string;
  /** Shown until the image loads (e.g. the user's initials). */
  fallback: ReactNode;
  imageProps?: ComponentProps<typeof AvatarImage>;
  fallbackProps?: ComponentProps<typeof AvatarFallback>;
}

/**
 * Avatar with an image and a fallback. `className` and `size` style the round
 * frame only; the image and fallback keep their own shape so a border or
 * background set on the frame is never repeated inside the clip.
 */
const Avatar = ({
  src,
  alt,
  fallback,
  imageProps,
  fallbackProps,
  ...rest
}: AvatarProps) => (
  <AvatarRoot {...rest}>
    <AvatarFallback {...fallbackProps}>{fallback}</AvatarFallback>

    <AvatarImage src={src ?? undefined} alt={alt ?? "Avatar"} {...imageProps} />
  </AvatarRoot>
);

export {
  Avatar,
  AvatarFallback,
  AvatarImage,
  type AvatarProps,
  AvatarProvider,
  AvatarRoot,
  useAvatar,
};

import { ark } from "@ark-ui/react";
import { cva } from "class-variance-authority";

import { cn } from "@/lib/utils";

import type { VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";

const buttonVariants = cva(
  "focus-visible:ring-offset-background focus-visible:ring-primary aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap outline-hidden transition-[color,box-shadow,transform] outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        solid:
          "bg-primary text-primary-foreground hover:bg-primary/90 shadow-xs",
        outline:
          "bg-background hover:bg-accent hover:text-accent-foreground border shadow-xs",
        muted: "bg-muted text-muted-foreground hover:bg-muted/80 shadow-xs",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-2 hover:underline",
        destructive:
          "bg-destructive text-background hover:bg-destructive/90 shadow-xs focus-visible:ring-red-500 aria-invalid:ring-red-500/20 dark:aria-invalid:ring-red-500/40",
        // no-style escape hatch: render the bare element and style it via
        // className (widely used downstream for icon/link-like buttons)
        unstyled: "",
      },
      size: {
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        md: "h-9 px-4 py-2 has-[>svg]:px-3",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "solid",
      size: "md",
    },
  },
);

const Button = ({
  className,
  variant,
  size,
  ...rest
}: ComponentProps<typeof ark.button> & VariantProps<typeof buttonVariants>) => (
  <ark.button
    type="button"
    className={cn(buttonVariants({ variant, size }), className)}
    {...rest}
  />
);

export { Button, buttonVariants };

import { Menu as ArkMenu } from "@ark-ui/react/menu";
import { Check, ChevronRight } from "lucide-react";

import { cn } from "@/lib/utils";

import type { ark } from "@ark-ui/react";
import type { ComponentProps } from "react";

const MenuProvider = ArkMenu.RootProvider;
const MenuRoot = ArkMenu.Root;
const MenuContextTrigger = ArkMenu.ContextTrigger;
const PrimitiveMenuIndicator = ArkMenu.ItemIndicator;

/**
 * Opens the menu. Shows a pointer, a keyboard focus ring, and a disabled state
 * whether it renders its own button or wraps a child via `asChild`
 */
const MenuTrigger = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Trigger>) => (
  <ArkMenu.Trigger
    className={cn(
      "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50",
      className,
    )}
    {...rest}
  />
);

const MenuPositioner = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Positioner>) => (
  <ArkMenu.Positioner className={className} {...rest} />
);

/**
 * Menu panel. Capped to the viewport space the positioner reports
 * (`--available-height`) and scrolls past it, so a long menu never runs off
 * screen with its bottom entries unreachable
 */
const MenuContent = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Content>) => (
  <ArkMenu.Content
    className={cn(
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 flex max-h-(--available-height) min-w-32 origin-(--transform-origin) flex-col gap-0.5 overflow-y-auto overflow-x-hidden overscroll-contain rounded-md border bg-popover p-1 text-popover-foreground shadow-md outline-none duration-300 data-[state=closed]:animate-out data-[state=open]:animate-in",
      className,
    )}
    {...rest}
  />
);

const MenuArrow = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Arrow>) => (
  <ArkMenu.Arrow className={cn("fill-popover", className)} {...rest} />
);

const MenuArrowTip = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ArrowTip>) => (
  <ArkMenu.ArrowTip className={cn("fill-border", className)} {...rest} />
);

const MenuItem = ({
  className,
  children,
  variant = "default",
  ...rest
}: ComponentProps<typeof ArkMenu.Item> & {
  variant?: "default" | "destructive";
}) => (
  <ArkMenu.Item
    data-variant={variant}
    className={cn(
      "relative flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden hover:bg-muted focus:bg-muted data-disabled:pointer-events-none data-[state=checked]:bg-muted data-highlighted:bg-muted data-inset:pl-8 data-[variant=destructive]:text-destructive data-disabled:opacity-50 data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:hover:bg-destructive/10 dark:data-[variant=destructive]:hover:bg-destructive/20 [&[data-state=checked][data-highlighted]]:bg-muted [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 data-[variant=destructive]:*:[svg]:text-destructive!",
      variant === "destructive" &&
        "data-highlighted:bg-destructive/10 data-highlighted:text-destructive",
      className,
    )}
    {...rest}
  >
    {children}
  </ArkMenu.Item>
);

const MenuCheckboxItem = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ArkMenu.CheckboxItem>) => (
  <ArkMenu.CheckboxItem
    className={cn(
      "relative flex w-full cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none hover:bg-muted focus:bg-muted data-disabled:pointer-events-none data-[state=checked]:bg-muted data-highlighted:bg-muted data-disabled:opacity-50 [&[data-state=checked][data-highlighted]]:bg-muted",
      className,
    )}
    {...rest}
  >
    {children}
  </ArkMenu.CheckboxItem>
);

const MenuItemGroup = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemGroup>) => (
  <ArkMenu.ItemGroup className={cn("overflow-hidden", className)} {...rest} />
);

const MenuItemGroupLabel = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemGroupLabel>) => (
  <ArkMenu.ItemGroupLabel
    className={cn(
      "flex w-full cursor-default items-center justify-between p-2 font-medium text-foreground text-sm",
      className,
    )}
    {...rest}
  />
);

const MenuItemText = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemText>) => (
  <ArkMenu.ItemText className={className} {...rest} />
);

const MenuItemIndicator = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.ItemIndicator>) => (
  <ArkMenu.ItemIndicator
    className={cn(
      "ml-auto flex h-3.5 w-3.5 items-center justify-center",
      className,
    )}
    {...rest}
  >
    <Check className="size-4" />
  </ArkMenu.ItemIndicator>
);

const MenuRadioItem = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ArkMenu.RadioItem>) => (
  <ArkMenu.RadioItem
    className={cn(
      "relative flex cursor-pointer select-none items-center gap-2 rounded-sm py-1.5 pr-2 pl-8 text-sm outline-hidden hover:bg-muted focus:bg-muted data-highlighted:bg-muted data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
      className,
    )}
    {...rest}
  >
    {children}
  </ArkMenu.RadioItem>
);

const MenuRadioItemGroup = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.RadioItemGroup>) => (
  <ArkMenu.RadioItemGroup className={className} {...rest} />
);

const MenuSeparator = ({
  className,
  ...rest
}: ComponentProps<typeof ArkMenu.Separator>) => (
  <ArkMenu.Separator
    className={cn("-mx-1 mt-1 mb-1 h-px bg-border", className)}
    {...rest}
  />
);

const MenuTriggerItem = ({
  className,
  children,
  ...rest
}: ComponentProps<typeof ArkMenu.TriggerItem>) => (
